document.getElementById('copy').addEventListener('click', async (e) => {
  const btn = e.currentTarget;
  try {
    await navigator.clipboard.writeText(document.getElementById('u').textContent.trim());
    btn.textContent = 'copied';
  } catch {
    // Clipboard is blocked in some embedded browsers — select it instead so
    // the manual copy still works rather than leaving the button dead.
    const r = document.createRange();
    r.selectNodeContents(document.getElementById('u'));
    const s = getSelection(); s.removeAllRanges(); s.addRange(r);
    btn.textContent = 'select + copy';
  }
  setTimeout(() => { btn.textContent = 'copy'; }, 2400);
});

